{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2148-03-26 20:15:00",
      "speaker": "Doctor",
      "text": "Hi Mr. ___, I'm Dr. ___. You're in the hospital because of left flank pain, fevers, and your nephrostomy tube isn’t draining well. We did a quick ultrasound in the ER and saw that your left kidney is very swollen. We’re concerned this is due to a blockage in your PCN tube."
    },
    {
      "turn_number": 2,
      "time": "2148-03-26 20:17:00",
      "speaker": "Patient",
      "text": "Yeah, it’s been hurting more than usual. The tube’s been draining less, and I’ve felt feverish. Is that why my kidney’s swollen?"
    },
    {
      "turn_number": 3,
      "time": "2148-03-26 20:19:00",
      "speaker": "Doctor",
      "text": "Exactly. The tube is supposed to drain urine from your kidney, but it looks blocked. That’s causing pressure and infection. We’ve scheduled a procedure to replace it tomorrow morning."
    },
    {
      "turn_number": 4,
      "time": "2148-03-26 20:21:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense. I’ve had this before. But this time it feels worse."
    },
    {
      "turn_number": 5,
      "time": "2148-03-26 20:22:00",
      "speaker": "Doctor",
      "text": "Yes, your white blood cell count is elevated, and your urine from the tube was cloudy. That suggests a significant infection. We’ll start IV antibiotics once the tube is replaced."
    },
    {
      "turn_number": 6,
      "time": "2148-03-26 20:24:00",
      "speaker": "Patient",
      "text": "I’m on a lot of meds already. Will they interact?"
    },
    {
      "turn_number": 7,
      "time": "2148-03-26 20:26:00",
      "speaker": "Doctor",
      "text": "We’ve reviewed your list. You’re on meropenem, which is safe given your allergies. We’ll adjust doses for your kidney function."
    },
    {
      "turn_number": 8,
      "time": "2148-03-27 08:30:00",
      "speaker": "Doctor",
      "text": "Good morning. You had the PCN tube exchange this morning. It went well. The old tube was clogged and partially pulled out. We placed a new one, and 250 cc of cloudy fluid drained out."
    },
    {
      "turn_number": 9,
      "time": "2148-03-27 08:32:00",
      "speaker": "Patient",
      "text": "That’s a lot. Was it infected?"
    },
    {
      "turn_number": 10,
      "time": "2148-03-27 08:34:00",
      "speaker": "Doctor",
      "text": "Yes, we sent it for culture. In the meantime, you’re on IV meropenem to treat the infection. Your pain should start improving."
    },
    {
      "turn_number": 11,
      "time": "2148-03-27 08:36:00",
      "speaker": "Patient",
      "text": "I’m still hurting pretty bad. Can I get something stronger?"
    },
    {
      "turn_number": 12,
      "time": "2148-03-27 08:38:00",
      "speaker": "Doctor",
      "text": "We’ve ordered IV Dilaudid for breakthrough pain. We’ll monitor your intake since you’re not eating much."
    },
    {
      "turn_number": 13,
      "time": "2148-03-27 14:00:00",
      "speaker": "Doctor",
      "text": "Your labs show your kidney function is stable—creatinine is 4.1, which is your baseline. We’re watching it closely."
    },
    {
      "turn_number": 14,
      "time": "2148-03-27 14:02:00",
      "speaker": "Patient",
      "text": "Good. I don’t want it getting worse. What about the infection?"
    },
    {
      "turn_number": 15,
      "time": "2148-03-27 14:04:00",
      "speaker": "Doctor",
      "text": "We’re waiting on culture results. For now, meropenem is covering the likely bacteria. We’ll adjust if needed."
    },
    {
      "turn_number": 16,
      "time": "2148-03-28 09:00:00",
      "speaker": "Doctor",
      "text": "We did an ultrasound yesterday. No abscess, and the left kidney isn’t hydronephrotic anymore. That means the new tube is working."
    },
    {
      "turn_number": 17,
      "time": "2148-03-28 09:02:00",
      "speaker": "Patient",
      "text": "That’s good. My pain is a little better."
    },
    {
      "turn_number": 18,
      "time": "2148-03-28 09:04:00",
      "speaker": "Doctor",
      "text": "We also saw your kidneys are echogenic, which fits with your chronic kidney disease. Nothing new there."
    },
    {
      "turn_number": 19,
      "time": "2148-03-29 10:00:00",
      "speaker": "Doctor",
      "text": "The culture from your PCN fluid came back. It grew Staphylococcus aureus, but it’s methicillin-sensitive, which is good."
    },
    {
      "turn_number": 20,
      "time": "2148-03-29 10:02:00",
      "speaker": "Patient",
      "text": "Is that serious?"
    },
    {
      "turn_number": 21,
      "time": "2148-03-29 10:04:00",
      "speaker": "Doctor",
      "text": "It’s treatable. We’re switching from meropenem to IV daptomycin, which works well for this bug. You’ll need a 14-day course."
    },
    {
      "turn_number": 22,
      "time": "2148-03-29 10:06:00",
      "speaker": "Patient",
      "text": "Fourteen days? I’ll have to stay here that long?"
    },
    {
      "turn_number": 23,
      "time": "2148-03-29 10:08:00",
      "speaker": "Doctor",
      "text": "Ideally, yes. We can arrange a PICC line so you can get antibiotics at home, or go to rehab."
    },
    {
      "turn_number": 24,
      "time": "2148-03-29 10:10:00",
      "speaker": "Patient",
      "text": "I don’t want a PICC. I’ve had infections before. And I can’t go to rehab."
    },
    {
      "turn_number": 25,
      "time": "2148-03-29 10:12:00",
      "speaker": "Doctor",
      "text": "We understand. But stopping early could lead to relapse. We’ll discuss options."
    },
    {
      "turn_number": 26,
      "time": "2148-03-30 08:00:00",
      "speaker": "Doctor",
      "text": "Your potassium is high—6.1. It’s something we watch with kidney disease."
    },
    {
      "turn_number": 27,
      "time": "2148-03-30 08:02:00",
      "speaker": "Patient",
      "text": "Is that dangerous?"
    },
    {
      "turn_number": 28,
      "time": "2148-03-30 08:04:00",
      "speaker": "Doctor",
      "text": "It can affect your heart, but your EKG is normal. We’d like to give you kayexalate to bring it down."
    },
    {
      "turn_number": 29,
      "time": "2148-03-30 08:06:00",
      "speaker": "Patient",
      "text": "No, I can’t. It gives me terrible diarrhea, and I already struggle with bowel issues."
    },
    {
      "turn_number": 30,
      "time": "2148-03-30 08:08:00",
      "speaker": "Doctor",
      "text": "We respect that. We’ll monitor it and recheck tomorrow. You should check it as an outpatient."
    },
    {
      "turn_number": 31,
      "time": "2148-03-31 09:00:00",
      "speaker": "Doctor",
      "text": "Blood cultures came back negative. That’s good—means the infection is likely localized to the kidney."
    },
    {
      "turn_number": 32,
      "time": "2148-03-31 09:02:00",
      "speaker": "Patient",
      "text": "So the antibiotics are working?"
    },
    {
      "turn_number": 33,
      "time": "2148-03-31 09:04:00",
      "speaker": "Doctor",
      "text": "Looks like it. Your white count is coming down. But you’ve only had 5 days of daptomycin. You need 14."
    },
    {
      "turn_number": 34,
      "time": "2148-03-31 09:06:00",
      "speaker": "Patient",
      "text": "I know, but I can’t stay. I’ll take it at home somehow."
    },
    {
      "turn_number": 35,
      "time": "2148-04-01 10:00:00",
      "speaker": "Doctor",
      "text": "We’ve spoken with urology. Your PCN is draining well. They’ll see you as an outpatient."
    },
    {
      "turn_number": 36,
      "time": "2148-04-01 10:02:00",
      "speaker": "Patient",
      "text": "Good. What about my leg? It’s been aching."
    },
    {
      "turn_number": 37,
      "time": "2148-04-01 10:04:00",
      "speaker": "Doctor",
      "text": "Ortho reviewed your old fracture. You have a healing tibia fracture. They recommend follow-up, but no urgent action."
    },
    {
      "turn_number": 38,
      "time": "2148-04-01 10:06:00",
      "speaker": "Patient",
      "text": "I haven’t gone yet. I’ll try to make the appointment."
    },
    {
      "turn_number": 39,
      "time": "2148-04-02 08:00:00",
      "speaker": "Doctor",
      "text": "We’re on day 7 of antibiotics. Your creatinine is stable at 3.9, and potassium is 6.0—still high but not worsening."
    },
    {
      "turn_number": 40,
      "time": "2148-04-02 08:02:00",
      "speaker": "Patient",
      "text": "I feel better, but still tired."
    },
    {
      "turn_number": 41,
      "time": "2148-04-02 08:04:00",
      "speaker": "Doctor",
      "text": "That’s expected. Infection takes a toll. We’re planning to taper your IV pain meds and switch back to your oral meds."
    },
    {
      "turn_number": 42,
      "time": "2148-04-02 08:06:00",
      "speaker": "Patient",
      "text": "I need those for pain. Don’t stop them too fast."
    },
    {
      "turn_number": 43,
      "time": "2148-04-02 08:08:00",
      "speaker": "Doctor",
      "text": "We’ll go slow. But we need to prepare for discharge. We’re concerned about finishing the antibiotic course."
    },
    {
      "turn_number": 44,
      "time": "2148-04-02 08:10:00",
      "speaker": "Patient",
      "text": "I’ll manage it. I don’t want to stay longer."
    },
    {
      "turn_number": 45,
      "time": "2148-04-03 09:00:00",
      "speaker": "Doctor",
      "text": "Today is day 8 of antibiotics. We’ve discussed options: home health, outpatient infusion, or stopping early."
    },
    {
      "turn_number": 46,
      "time": "2148-04-03 09:02:00",
      "speaker": "Patient",
      "text": "I don’t want any of those. I’ll take my chances."
    },
    {
      "turn_number": 47,
      "time": "2148-04-03 09:04:00",
      "speaker": "Doctor",
      "text": "We strongly advise completing the course. Incomplete treatment could lead to relapse or resistance."
    },
    {
      "turn_number": 48,
      "time": "2148-04-03 09:06:00",
      "speaker": "Patient",
      "text": "I understand, but I’m leaving. I’ve been here too long."
    },
    {
      "turn_number": 49,
      "time": "2148-04-03 09:08:00",
      "speaker": "Doctor",
      "text": "We’ll document your decision. Please follow up with urology, nephrology, and check your potassium."
    },
    {
      "turn_number": 50,
      "time": "2148-04-03 09:10:00",
      "speaker": "Patient",
      "text": "I’ll try. I know I need to."
    },
    {
      "turn_number": 51,
      "time": "2148-04-03 14:00:00",
      "speaker": "Doctor",
      "text": "We’ve been informed you’re planning to leave. We want to make sure you know the risks."
    },
    {
      "turn_number": 52,
      "time": "2148-04-03 14:02:00",
      "speaker": "Patient",
      "text": "I’ve made up my mind. I’m not staying for two more weeks."
    },
    {
      "turn_number": 53,
      "time": "2148-04-03 14:04:00",
      "speaker": "Doctor",
      "text": "Okay. Your PCN is working, pain is better, and labs are stable. But you’ve only had 8 of 14 antibiotic days."
    },
    {
      "turn_number": 54,
      "time": "2148-04-03 14:06:00",
      "speaker": "Patient",
      "text": "I’ll rest at home. I’ll call if I get worse."
    },
    {
      "turn_number": 55,
      "time": "2148-04-03 14:08:00",
      "speaker": "Doctor",
      "text": "Please do. And follow up with your doctors. Your urine test also showed cocaine. We’re concerned about your use."
    },
    {
      "turn_number": 56,
      "time": "2148-04-03 14:10:00",
      "speaker": "Patient",
      "text": "I… I lost a close friend. I’ve been struggling. I slipped back."
    },
    {
      "turn_number": 57,
      "time": "2148-04-03 14:12:00",
      "speaker": "Doctor",
      "text": "We’re sorry to hear that. We’ve connected you with counseling resources. Please consider reaching out."
    },
    {
      "turn_number": 58,
      "time": "2148-04-03 14:14:00",
      "speaker": "Patient",
      "text": "I will. I know I need help."
    },
    {
      "turn_number": 59,
      "time": "2148-04-03 14:16:00",
      "speaker": "Doctor",
      "text": "Take care of yourself. We’ll send your records to your providers. Please come back if you develop fever, pain, or swelling."
    },
    {
      "turn_number": 60,
      "time": "2148-04-03 14:18:00",
      "speaker": "Patient",
      "text": "I will. Thank you for everything."
    },
    {
      "turn_number": 61,
      "time": "2148-04-04 00:15:00",
      "speaker": "Doctor",
      "text": "Mr. ___, you were supposed to be discharged this morning, but we’ve been informed you left the hospital last night."
    },
    {
      "turn_number": 62,
      "time": "2148-04-04 00:17:00",
      "speaker": "Patient",
      "text": "Yes, I had to go. I couldn’t stay any longer."
    },
    {
      "turn_number": 63,
      "time": "2148-04-04 00:19:00",
      "speaker": "Doctor",
      "text": "We understand, but it’s important you follow up. Your infection isn’t fully treated, and your potassium is still high."
    },
    {
      "turn_number": 64,
      "time": "2148-04-04 00:21:00",
      "speaker": "Patient",
      "text": "I know. I’ll call urology. I’ll be careful."
    },
    {
      "turn_number": 65,
      "time": "2148-04-04 00:23:00",
      "speaker": "Doctor",
      "text": "Please do. And consider speaking with someone about your loss and substance use. You’re not alone."
    },
    {
      "turn_number": 66,
      "time": "2148-04-04 00:25:00",
      "speaker": "Patient",
      "text": "I’ll think about it. Thanks again."
    },
    {
      "turn_number": 67,
      "time": "2148-04-04 08:00:00",
      "speaker": "Doctor",
      "text": "We’ve updated your discharge plan. You eloped before formal discharge, but we’re documenting your care."
    },
    {
      "turn_number": 68,
      "time": "2148-04-04 08:02:00",
      "speaker": "Patient",
      "text": "I just needed to go home."
    },
    {
      "turn_number": 69,
      "time": "2148-04-04 08:04:00",
      "speaker": "Doctor",
      "text": "We respect that. Just remember: finish your follow-ups, check your potassium, and call if you’re not feeling well."
    },
    {
      "turn_number": 70,
      "time": "2148-04-04 08:06:00",
      "speaker": "Patient",
      "text": "I will. I don’t want to end up back here."
    },
    {
      "turn_number": 71,
      "time": "2148-04-04 08:08:00",
      "speaker": "Doctor",
      "text": "We hope not either. Take care of yourself, Mr. ___."
    },
    {
      "turn_number": 72,
      "time": "2148-04-04 08:10:00",
      "speaker": "Patient",
      "text": "I’ll try. Thank you."
    },
    {
      "turn_number": 73,
      "time": "2148-04-04 10:00:00",
      "speaker": "Doctor",
      "text": "Final update: your PCN is functioning, infection markers improved, but antibiotic course incomplete. Follow-up critical."
    },
    {
      "turn_number": 74,
      "time": "2148-04-04 10:02:00",
      "speaker": "Patient",
      "text": "I’ll make the calls today."
    },
    {
      "turn_number": 75,
      "time": "2148-04-04 10:04:00",
      "speaker": "Doctor",
      "text": "We’ll send your meds list and records. Please stay in touch with your team."
    },
    {
      "turn_number": 76,
      "time": "2148-04-04 10:06:00",
      "speaker": "Patient",
      "text": "I will. I appreciate everything."
    },
    {
      "turn_number": 77,
      "time": "2148-04-04 10:08:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. ___. We’re here if you need us."
    },
    {
      "turn_number": 78,
      "time": "2148-04-04 10:10:00",
      "speaker": "Patient",
      "text": "Thanks. I’ll be okay."
    },
    {
      "turn_number": 79,
      "time": "2148-04-04 11:00:00",
      "speaker": "Doctor",
      "text": "We’ve finalized your discharge. You’ve completed 8 of 14 antibiotic days. Please follow up as discussed."
    },
    {
      "turn_number": 80,
      "time": "2148-04-04 11:02:00",
      "speaker": "Patient",
      "text": "I’ll do my best."
    },
    {
      "turn_number": 81,
      "time": "2148-04-04 11:04:00",
      "speaker": "Doctor",
      "text": "That’s all we can ask. Stay safe, Mr. ___."
    },
    {
      "turn_number": 82,
      "time": "2148-04-04 11:06:00",
      "speaker": "Patient",
      "text": "I will. Thank you."
    },
    {
      "turn_number": 83,
      "time": "2148-04-04 11:08:00",
      "speaker": "Doctor",
      "text": "We’ve documented your elopement. Please contact us if symptoms return."
    },
    {
      "turn_number": 84,
      "time": "2148-04-04 11:10:00",
      "speaker": "Patient",
      "text": "I will. I don’t want this to happen again."
    },
    {
      "turn_number": 85,
      "time": "2148-04-04 11:12:00",
      "speaker": "Doctor",
      "text": "We hope not. Take care of yourself, Mr. ___."
    }
  ],
  "summary": {
    "admission_start": "2148-03-26 19:54:00",
    "admission_end": "2148-04-04 12:50:00",
    "summary_paragraph": "Mr. ___ was admitted with left flank pain, fevers, and decreased output from his left nephrostomy tube, found to be occluded. He underwent successful PCN tube exchange with drainage of infected fluid. Cultures grew methicillin-sensitive Staphylococcus aureus, and he was started on IV daptomycin for a planned 14-day course. His chronic kidney disease remained stable, but he developed hyperkalemia (K 6.1), which he declined treatment for. He also acknowledged recent cocaine use related to grief over a friend’s death. Despite medical advice, he eloped on hospital day 8, having completed only part of his antibiotic course. He was alert and stable at the time, with functioning PCN and improved pain, but was strongly advised to follow up with urology, nephrology, and outpatient support.",
    "problems": [
      "Other mechanical complication of nephrostomy catheter, initial encounter",
      "Chronic kidney disease, stage 4 (severe)",
      "Hyperkalemia",
      "Cocaine abuse, uncomplicated",
      "Pyelonephritis",
      "Paraplegia, unspecified",
      "Other artificial openings of urinary tract status",
      "Patient's noncompliance with other medical treatment and regimen"
    ]
  }
}
